"""Хранилище в памяти: справочник SKU и физические остатки по складам."""

from __future__ import annotations

from typing import Iterator

from .models import Reservation, Sku


class InMemoryStore:
    """Простое хранилище. Ничего не проверяет — проверки живут в сервисе."""

    def __init__(self) -> None:
        self._skus: dict[str, Sku] = {}
        self._quantities: dict[tuple[str, str], int] = {}
        self._reservations: dict[str, Reservation] = {}

    # --- справочник ---------------------------------------------------------

    def add_sku(self, sku: Sku) -> None:
        self._skus[sku.code] = sku

    def get_sku(self, code: str) -> Sku | None:
        return self._skus.get(code)

    def has_sku(self, code: str) -> bool:
        return code in self._skus

    def list_skus(self) -> list[Sku]:
        return sorted(self._skus.values(), key=lambda sku: sku.code)

    # --- остатки ------------------------------------------------------------

    def get_qty(self, warehouse: str, sku: str) -> int:
        return self._quantities.get((warehouse, sku), 0)

    def set_qty(self, warehouse: str, sku: str, qty: int) -> None:
        if qty == 0:
            self._quantities.pop((warehouse, sku), None)
        else:
            self._quantities[(warehouse, sku)] = qty

    def positions(self) -> Iterator[tuple[str, str, int]]:
        """Все ненулевые позиции ``(warehouse, sku, qty)`` в стабильном порядке."""
        for (warehouse, sku), qty in sorted(self._quantities.items()):
            yield warehouse, sku, qty

    def warehouses(self) -> list[str]:
        return sorted({warehouse for warehouse, _ in self._quantities})

    # --- резервы ------------------------------------------------------------

    def get_reservation(self, order_id: str) -> Reservation | None:
        return self._reservations.get(order_id)

    def put_reservation(self, reservation: Reservation) -> None:
        self._reservations[reservation.order_id] = reservation

    def reservations(self) -> list[Reservation]:
        return list(self._reservations.values())
"""Отчёты по остаткам и движению. Только чтение, ничего не меняют."""

from __future__ import annotations

import csv
import io
import logging
from dataclasses import dataclass
from datetime import datetime

from .events import EventLog
from .inventory import Inventory

logger = logging.getLogger(__name__)


@dataclass(frozen=True)
class Movement:
    """Сводка движения по SKU за период."""

    sku: str
    received: int = 0
    issued: int = 0
    adjusted: int = 0

    @property
    def net(self) -> int:
        return self.received - self.issued + self.adjusted


def stock_report(inventory: Inventory, warehouse: str | None = None) -> str:
    """Текстовая таблица физических остатков."""
    levels = inventory.stock_levels(warehouse)
    if not levels:
        return "(no stock)"
    rows = [("WAREHOUSE", "SKU", "NAME", "ON HAND")]
    for level in levels:
        sku = inventory.get_sku(level.sku)
        rows.append((level.warehouse, level.sku, sku.name, f"{level.on_hand} {sku.unit}"))
    widths = [max(len(row[i]) for row in rows) for i in range(4)]
    lines = []
    for row in rows:
        cells = [row[i].ljust(widths[i]) for i in range(3)] + [row[3].rjust(widths[3])]
        lines.append("  ".join(cells).rstrip())
    return "\n".join(lines)


def stock_csv(inventory: Inventory) -> str:
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["warehouse", "sku", "on_hand"])
    for level in inventory.stock_levels():
        writer.writerow([level.warehouse, level.sku, level.on_hand])
    return buffer.getvalue()


def low_stock(inventory: Inventory, threshold: int) -> list[tuple[str, str, int]]:
    """Позиции, физический остаток которых ниже порога (нулевые не попадают)."""
    return [
        (level.warehouse, level.sku, level.on_hand)
        for level in inventory.stock_levels()
        if level.on_hand < threshold
    ]


def movement_summary(
    log: EventLog, since: datetime | None = None, until: datetime | None = None
) -> dict[str, Movement]:
    """Приход/расход/корректировки по SKU за полуинтервал ``[since, until)``.

    Перемещения между складами в сводку не входят: для компании в целом
    это не движение товара.
    """
    totals: dict[str, dict[str, int]] = {}
    for event in log:
        if since is not None and event.ts < since:
            continue
        if until is not None and event.ts >= until:
            continue
        sku = event.get("sku")
        if sku is None:
            continue
        bucket = totals.setdefault(sku, {"received": 0, "issued": 0, "adjusted": 0})
        if event.kind == "RECEIVE":
            bucket["received"] += int(event.fields["qty"])
        elif event.kind == "ISSUE":
            bucket["issued"] += int(event.fields["qty"])
        elif event.kind == "ADJUST":
            bucket["adjusted"] += int(event.fields["delta"])
    logger.debug("movement summary for %d SKUs", len(totals))
    return {sku: Movement(sku=sku, **values) for sku, values in sorted(totals.items())}
