    EXPIRED = "expired"
    CONFIRMED = "confirmed"
    CANCELLED = "cancelled"


@dataclass(frozen=True)
class ReservationLine:
    """Строка резерва: сколько единиц SKU держим на складе."""

    warehouse: str
    sku: str
    qty: int


@dataclass(frozen=True)
class Reservation:
    """Снимок резерва под заказ. ``status`` — на момент запроса."""

    order_id: str
    lines: tuple[ReservationLine, ...]
    created_at: datetime
    expires_at: datetime
    status: ReservationStatus


@dataclass(frozen=True)
class Sku:
    """Позиция справочника номенклатуры."""

    code: str
    name: str
    unit: str = "pcs"


@dataclass(frozen=True)
class StockLevel:
    """Физический остаток SKU на конкретном складе."""

    warehouse: str
    sku: str
    on_hand: int
